import java.util.function.Supplier;

public class ErasureWorkaround {
  static <T> List<T> createList(Supplier<T> factory, int n) {
    List<T> list = new ArrayList<>();
    for (int i = 0; i < n; i++) list.add(factory.get());
    return list;
  }

  @SuppressWarnings("unchecked")
  static <T> T[] newArray(Class<T> clazz, int n) {
    return (T[]) java.lang.reflect.Array.newInstance(clazz, n);
  }

  public static void main(String[] args) {
    List<StringBuilder> list = createList(StringBuilder::new, 3);
    System.out.println(list.size());

    String[] arr = newArray(String.class, 5);
    System.out.println(arr.length);
  }
}

