public class BoundDemo {
  static <T extends Comparable<T>> T max(List<T> list) {
    T best = list.get(0);
    for (T t : list) {
      if (t.compareTo(best) > 0) best = t;
    }
    return best;
  }

  static <T extends Number & Comparable<T>> double sum(List<T> list) {
    double s = 0;
    for (T t : list) s += t.doubleValue();
    return s;
  }

