import java.util.*;

public class IterRemove {
  public static void main(String[] args) {
    List<String> a = new ArrayList<>(Arrays.asList("a1", "b1", "a2"));
    try {
      for (String s : a) {
        if (s.startsWith("a")) a.remove(s);
      }
    } catch (ConcurrentModificationException e) {
      System.out.println("for-each 删除失败");
    }

    List<String> b = new ArrayList<>(Arrays.asList("a1", "b1", "a2"));
    Iterator<String> it = b.iterator();
    while (it.hasNext()) {
      if (it.next().startsWith("a")) it.remove();
    }
    System.out.println(b);

    List<String> c = new ArrayList<>(Arrays.asList("a1", "b1", "a2"));
    c.removeIf(s -> s.startsWith("a"));
    System.out.println(c);
  }
}

